SELECT t0.code AS "Code",t0.amount AS "Amount" FROM (SELECT t1.code AS "code",t1.amount AS "amount",t1.in_z AS "in_z",t1.out_z AS "out_z",t1.from_z AS "from_z",t1.thru_z AS "thru_z" FROM org.quotes AS t1 WHERE t1.amount IS NOT NULL) AS t0 WHERE t0.in_z <= '2021-06-01 00:00:00' AND t0.out_z > '2021-06-01 00:00:00' AND t0.from_z <= '2021-06-01' AND t0.thru_z > '2021-06-01' ORDER BY t0.code ASC NULLS FIRST
